B.OC={"Python Variables":0,"Python Data Types":1,"Python Input and Output":2,"Python Operators":3,"Python Conditional Statements":4,"Python Loops":5,"Python Functions":6,"Machine Learning Basics":7,"Machine Learning with Libraries":8}
B.OR={"Variables 1: Student Introduction":0,"Variables 2: School Bag Items":1,"Variables 3: Marks Update":2}
B.NE=new A.bA(B.OR,['# A variable stores a value so we can use it later.\n# Here we save three pieces of information about one student.\nstudent_name = "Aarav"\nstudent_class = 6\nfavorite_subject = "Science"\n\n# print() shows the value stored inside each variable.\nprint("Student name:", student_name)\nprint("Class:", student_class)\nprint("Favorite subject:", favorite_subject)\n','# Variables can change while the program runs.\n# We start with 4 notebooks and 1 water bottle.\nnotebooks = 4\nwater_bottle = 1\n\n# Add 2 more notebooks to the old value.\nnotebooks = notebooks + 2\n\n# Display the updated values.\nprint("Notebooks now:", notebooks)\nprint("Water bottles:", water_bottle)\n','# Store the first marks value in a variable.\nmath_marks = 72\nprint("Old math marks:", math_marks)\n\n# Replace the old value with a new one.\nmath_marks = 85\nprint("Updated math marks:", math_marks)\n'],t.l)
B.OP={"Data Types 1: Basic Types":0,"Data Types 2: List of Subjects":1,"Data Types 3: Student Record":2}
B.NH=new A.bA(B.OP,['# A string stores text.\nstudent_name = "Meera"\n# An integer stores whole numbers.\nage = 12\n# A float stores decimal numbers.\nheight = 4.8\n# A boolean stores True or False.\nlikes_python = True\n\n# type() tells us the data type of each value.\nprint(student_name, "->", type(student_name))\nprint(age, "->", type(age))\nprint(height, "->", type(height))\nprint(likes_python, "->", type(likes_python))\n','# A list stores many items in one variable.\nsubjects = ["English", "Math", "Science", "Computer"]\n\n# Print the full list.\nprint("Subjects:", subjects)\n# Index 0 means the first item in the list.\nprint("First subject:", subjects[0])\n# len() tells us how many items are inside the list.\nprint("How many subjects?", len(subjects))\n','# A dictionary stores information as key-value pairs.\nstudent = {\n    "name": "Riya",\n    "class": 7,\n    "house": "Blue"\n}\n\n# Print the whole dictionary.\nprint("Student record:", student)\n# Use keys like "name" and "house" to get specific values.\nprint("Name:", student["name"])\nprint("House:", student["house"])\n'],t.l)
B.OH={"Input Output 1: Friendly Greeting":0,"Input Output 2: Age Next Year":1,"Input Output 3: Two Numbers":2}
B.NW=new A.bA(B.OH,['# input() asks the user to type something.\nname = input("What is your name? ")\n\n# print() shows the typed answer on the screen.\nprint("Hello,", name)\nprint("Welcome to Python class!")\n','# input() gives text, so int() changes it into a whole number.\nage = int(input("Enter your age: "))\n\n# Add 1 to find the age for next year.\nnext_year_age = age + 1\n\nprint("Your age next year will be", next_year_age)\n','# Ask the user for two numbers.\nfirst_number = int(input("Enter first number: "))\nsecond_number = int(input("Enter second number: "))\n\n# Add them and store the answer.\ntotal = first_number + second_number\nprint("The sum is", total)\n'],t.l)
B.OF={"Operators 1: Arithmetic Practice":0,"Operators 2: Comparison Check":1,"Operators 3: Logical Decisions":2}
B.NQ=new A.bA(B.OF,['# Save two numbers for practice.\nnumber1 = 18\nnumber2 = 6\n\n# Use arithmetic operators to calculate answers.\nprint("Addition:", number1 + number2)\nprint("Subtraction:", number1 - number2)\nprint("Multiplication:", number1 * number2)\nprint("Division:", number1 / number2)\n','# Comparison operators check relationships between values.\nenglish = 78\nscience = 78\n\n# Each comparison gives a boolean result: True or False.\nprint("English > Science:", english > science)\nprint("English < Science:", english < science)\nprint("English == Science:", english == science)\n','# Logical operators combine boolean values.\nfinished_homework = True\nbrought_book = True\n\n# and is True only when both conditions are True.\nprint("Can join activity:", finished_homework and brought_book)\n# Here one condition is False, so the result becomes False.\nprint("Missed one requirement:", finished_homework and False)\n# or is True if at least one condition is True.\nprint("At least one is ready:", finished_homework or False)\n'],t.l)
B.OA={"Conditionals 1: Voting Style Check":0,"Conditionals 2: Pass or Improve":1,"Conditionals 3: School Uniform Advice":2}
B.O4=new A.bA(B.OA,['# The program checks a condition and chooses a path.\nage = 14\n\n# If age is 18 or more, run the first block.\nif age >= 18:\n    print("You are an adult.")\n# Otherwise, run the else block.\nelse:\n    print("You are not an adult yet.")\n','# elif lets us check another condition if the first one is False.\nmarks = 67\n\nif marks >= 90:\n    print("Excellent work!")\nelif marks >= 50:\n    print("You passed the test.")\nelse:\n    print("Keep practicing and try again.")\n','# Booleans are useful in conditions.\nis_raining = True\n\n# If it is raining, give one message.\nif is_raining:\n    print("Take an umbrella to school.")\n# If not, give a different message.\nelse:\n    print("Enjoy the sunny day.")\n'],t.l)
